<script setup lang="ts">
import type { Product } from '@ellas/shared';
useSeo('Catálogo JHK 2026', 'Explora todas las referencias del catálogo JHK: camisetas, polos, sudaderas y ropa laboral. Filtra por talla y color y prepara una solicitud para tu equipo.');
const route=useRoute(); const router=useRouter(); const filtersOpen=ref(false);
const keys=['q','category','collection','audience','size','color','composition','weight'] as const;
const query=computed(()=>Object.fromEntries([...keys,'page'].map(key=>[key,typeof route.query[key]==='string'?route.query[key]:''])));
const search=ref(String(route.query.q || ''));
watch(()=>route.query.q,value=>search.value=typeof value==='string'?value:'');
interface CatalogResult { products:Product[];total:number;pages:number;page:number;facets:{categories:string[];collections:string[];audiences:string[];sizes:string[];colors:{code:string;name:string;hex:string}[];compositions:string[];weights:string[]} }
const requestQuery=computed(()=>Object.fromEntries(Object.entries(query.value).filter(([,value])=>value)));
const {data,pending,error,refresh}=await useFetch<CatalogResult>('/api/catalog/products',{query:requestQuery});
function set(key:string,value:string){const next={...route.query,[key]:value || undefined,page:undefined};void router.push({query:next});}
function page(value:number){void router.push({query:{...route.query,page:value===1?undefined:String(value)}});window.scrollTo({top:120,behavior:'smooth'});}
const active=computed(()=>keys.filter(key=>query.value[key]));
</script>
<template><div class="container catalog-page"><div class="breadcrumb"><NuxtLink to="/">Inicio</NuxtLink><span>/</span><span>Catálogo</span></div><div class="catalog-intro"><div><span class="eyebrow">JHK COLLECTION / 2026</span><h1>Encuentra tu <span class="serif-word">equipo.</span></h1><p>Elige prendas. Combina tallas y colores. Haz una sola solicitud.</p></div><span class="catalog-note">Sin precios inventados.<br />Cada propuesta, a vuestra medida.</span></div><form class="catalog-search" @submit.prevent="set('q',search)"><AppIcon name="Search" /><input v-model="search" type="search" placeholder="Busca una prenda o referencia, por ejemplo JT150" aria-label="Buscar nombre o referencia" maxlength="100" /><button type="submit" class="button dark">Buscar <AppIcon name="ArrowRight" :size="17" /></button></form>
<div class="catalog-toolbar"><span><strong>{{data?.total ?? '—'}}</strong> prendas para descubrir</span><button class="button outline filter-toggle" @click="filtersOpen=!filtersOpen"><AppIcon name="SlidersHorizontal" :size="17" /> Filtros <span v-if="active.length" class="badge">{{active.length}}</span></button><span class="catalog-order">Referencia A–Z</span></div>
<div class="catalog-layout"><aside class="catalog-filters" :class="{'is-open':filtersOpen}" aria-label="Filtros del catálogo"><div class="filter-title"><h2>Afina tu búsqueda</h2><button class="icon-button mobile-only" aria-label="Cerrar filtros" @click="filtersOpen=false"><AppIcon name="X" /></button></div><template v-if="data"><label>Categoría<select :value="query.category" @change="set('category',($event.target as HTMLSelectElement).value)"><option value="">Todas las prendas</option><option v-for="value in data.facets.categories" :key="value">{{value}}</option></select></label><label>Colección<select :value="query.collection" @change="set('collection',($event.target as HTMLSelectElement).value)"><option value="">Todas las colecciones</option><option v-for="value in data.facets.collections" :key="value">{{value}}</option></select></label><label>Para quién<select :value="query.audience" @change="set('audience',($event.target as HTMLSelectElement).value)"><option value="">Todo el equipo</option><option v-for="value in data.facets.audiences" :key="value">{{value}}</option></select></label><label>Talla<select :value="query.size" @change="set('size',($event.target as HTMLSelectElement).value)"><option value="">Todas las tallas</option><option v-for="value in data.facets.sizes" :key="value">{{value}}</option></select></label><label>Color<select :value="query.color" @change="set('color',($event.target as HTMLSelectElement).value)"><option value="">Todos los colores</option><option v-for="color in data.facets.colors" :key="color.code" :value="color.code">{{color.name}} · {{color.code}}</option></select></label><label>Composición<select :value="query.composition" @change="set('composition',($event.target as HTMLSelectElement).value)"><option value="">Todos los tejidos</option><option v-for="value in data.facets.compositions" :key="value">{{value}}</option></select></label><label>Gramaje<select :value="query.weight" @change="set('weight',($event.target as HTMLSelectElement).value)"><option value="">Todos los gramajes</option><option v-for="value in data.facets.weights" :key="value">{{value}} g/m²</option></select></label></template><button v-if="active.length" class="text-link" @click="router.push({query:{}});search=''">Limpiar filtros <AppIcon name="X" :size="16" /></button><p class="filter-footnote">Las tallas y los colores se filtran por combinaciones válidas del catálogo. Su existencia en el catálogo no indica stock.</p></aside><div class="catalog-results" :aria-busy="pending"><div v-if="active.length" class="active-filters"><button v-for="key in active" :key="key" @click="set(key,'')">{{query[key]}} <AppIcon name="X" :size="13" /></button></div><div v-if="error" class="empty-state"><AppIcon name="Shirt" :size="40" /><h2>El catálogo necesita un momento</h2><p>No hemos podido conectar con el catálogo.</p><button class="button dark" @click="refresh()">Volver a intentar</button></div><template v-else-if="data?.products.length"><div class="product-grid"><ProductCard v-for="(product,index) in data.products" :key="product.reference" :product="product" :priority="index<3" /></div><nav v-if="data.pages>1" class="pagination" aria-label="Páginas del catálogo"><button :disabled="data.page<=1" aria-label="Página anterior" @click="page(data.page-1)"><AppIcon name="ChevronLeft" /></button><span>Página {{data.page}} de {{data.pages}}</span><button :disabled="data.page>=data.pages" aria-label="Página siguiente" @click="page(data.page+1)"><AppIcon name="ChevronRight" /></button></nav></template><div v-else-if="!pending" class="empty-state"><AppIcon name="Search" :size="40" /><h2>No encontramos esa combinación</h2><p>Prueba solo con la referencia o retira algún filtro.</p><NuxtLink to="/catalogo" class="button dark">Ver todas las prendas</NuxtLink></div></div></div></div></template>
